import { useState } from "react";

function App() {
  const [key, setKey] = useState("");
  const [user, setUser] = useState(null);
  const [error, setError] = useState("");

  const login = async () => {
    const res = await fetch("http://localhost:5000/login", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ key })
    });
    const data = await res.json();
    if (!res.ok) {
      setError(data.message);
      return;
    }
    setUser(data.user);
    setError("");
  };

  if (!user) {
    return (
      <div style={{ padding: 20 }}>
        <h1>Key Login</h1>
        <input
          value={key}
          onChange={(e) => setKey(e.target.value)}
          placeholder="Enter key"
        />
        <button onClick={login}>Login</button>
        {error && <p style={{ color: "red" }}>{error}</p>}
      </div>
    );
  }

  if (user.role === "patient") {
    return (
      <div>
        <h1>Welcome {user.name}</h1>
        <p>Age: {user.age}</p>
        <p>Sex: {user.sex}</p>
        <h3>Heart Rate Records</h3>
        <ul>
          {user.heart_rates.map((r, i) => (
            <li key={i}>
              {r.timestamp}: {r.heart_rate}
            </li>
          ))}
        </ul>
      </div>
    );
  }
  if (user.role === "doctor") {
  return (
    <div>
      <h1>Doctor Dashboard: {user.name}</h1>
      <table border="1" cellPadding="5">
        <thead>
          <tr>
            <th>User Info</th>
            <th>Most Recent Heart Rate</th>
            <th>Column 3</th>
            <th>Column 4</th>
          </tr>
        </thead>
        <tbody>
          {user.patients.map((p) => (
            <tr key={p.key}>
              <td>
                {p.name}, Age: {p.age}, Sex: {p.sex}
              </td>
              <td>{p.heart_rate || "-"}</td>
              <td></td>
              <td></td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

  return null;
}

export default App;
